<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
if(empty($_SESSION['admin'])||time()-(int)($_SESSION['last_seen']??0)>1800){http_response_code(403);exit('Inicia sesión en administración para configurar la medición.');}
$_SESSION['last_seen']=time();$appRoot=dirname((new ReflectionFunction('db'))->getFileName());require $appRoot.'/analytics/AnalyticsService.php';require $appRoot.'/analytics/BasicAudienceService.php';
$error='';$message='';$service=new AnalyticsService(db(),(string)$config['app_key']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();try{
  if(($_POST['action']??'')==='install'){
   $plan=json_decode(file_get_contents($appRoot.'/content/coverage-plan.json'),true,512,JSON_THROW_ON_ERROR);$geo=json_decode(file_get_contents($appRoot.'/content/coverage-geography.json'),true,512,JSON_THROW_ON_ERROR);$service->install($plan,$geo);$message='Medición habilitada y catálogo guardado en la base de datos. No se modificaron destinos ni negocios existentes.';
  }elseif(($_POST['action']??'')==='basic'){
   (new BasicAudienceService(db(),dirname(__DIR__)))->install();$message='Conteo básico agregado habilitado. No identifica visitantes ni crea cookies.';
  }elseif(($_POST['action']??'')==='place'){
   $id=(string)($_POST['place_id']??'');$preparing=($_POST['preparing']??'')==='1'?1:0;$q=db()->prepare('UPDATE el_coverage_places SET preparing=? WHERE id=?');$q->execute([$preparing,$id]);$message='Estado de preparación actualizado. Esto no publica ninguna guía.';
  }
 }catch(Throwable){$error='No se pudo completar la operación. No se muestran datos de conexión.';}
}
$ready=$service->ready();$counts=[];if($ready){foreach(['sessions'=>'el_measurement_sessions','events'=>'el_measurement_events','places'=>'el_coverage_places'] as $label=>$table)$counts[$label]=(int)db()->query("SELECT COUNT(*) FROM $table")->fetchColumn();}
$basic=new BasicAudienceService(db(),dirname(__DIR__));$basicReady=$basic->ready();$basicReport=$basic->report();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Medición y cobertura · Administración</title><link rel="stylesheet" href="../assets/cobertura/cobertura.css?v=9"></head><body><main><section class="intro"><p class="eyebrow">Administración privada</p><h1>Medición y cobertura</h1><p><a href="index.php">Volver a administración</a> · <a href="../cobertura/colombia/#audiencia">Ver audiencia pública</a></p></section><?php if($message):?><p class="notice"><?=esc($message)?></p><?php endif ?><?php if($error):?><p class="notice"><?=esc($error)?></p><?php endif ?>
<section><h2>Conteo básico de páginas sin cookies</h2><?php if($basicReady):?><p>Habilitado · <?=esc($basicReport['page_views'])?> páginas vistas en los últimos 30 días (calendario de Colombia). No equivale a personas ni sesiones.</p><?php else:?><p>Pendiente de activación. Guarda solamente totales diarios por portal/departamento, sin identificadores, IPs, país ni recorridos. Respeta DNT/GPC. El alojamiento puede conservar registros técnicos por separado.</p><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="basic"><button>Habilitar conteo básico agregado</button></form><?php endif ?></section><?php if(!$ready):?><section><h2>Activar medición propia</h2><p>Se crearán tablas nuevas para sesiones, eventos, controles de abuso y catálogo de cobertura. Se conservarán los datos actuales del portal. Solo se registrará actividad con aceptación de medición; no se almacenarán IPs ni contactos en eventos.</p><p>Países por consulta local DB-IP. Conservación de eventos: 180 días. Datos públicos agregados, con protección de grupos pequeños. Las cuentas viajeras se cuentan solo si están activas y confirmadas.</p><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="install"><button type="submit">Habilitar medición y crear tablas</button></form></section><?php else:?><section><h2>Medición habilitada</h2><p><?=esc($counts['sessions'])?> sesiones · <?=esc($counts['events'])?> eventos · <?=esc($counts['places'])?> lugares en la base.</p><p>Estas cifras privadas incluyen grupos pequeños; la página pública aplica umbrales de privacidad. Los ceros solo son válidos desde que comenzó la medición.</p><h2>Seguimiento de lugares</h2><p>Marcar “En preparación” no publica destinos. El estado público sigue dependiendo del catálogo de destinos.</p><?php $rows=db()->query('SELECT p.id,p.name,d.name AS department,p.preparing FROM el_coverage_places p JOIN el_coverage_departments d ON d.code=p.department_code ORDER BY d.name,p.name')->fetchAll();foreach($rows as $row):?><form method="post"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="place"><input type="hidden" name="place_id" value="<?=esc($row['id'])?>"><label><?=esc($row['name'].' · '.$row['department'])?><select name="preparing"><option value="0" <?=!$row['preparing']?'selected':''?>>Pendiente</option><option value="1" <?=$row['preparing']?'selected':''?>>En preparación</option></select></label><button>Guardar</button></form><?php endforeach ?></section><?php endif ?></main></body></html>
